python
# main.py
import asyncio
import re
import time
from urllib.parse import urljoin, urldefrag, urlparse
from typing import List, Dict, Optional, Set
import json

import httpx
from fastapi import FastAPI, WebSocket, WebSocketDisconnect, Query
from fastapi.responses import HTMLResponse, JSONResponse, FileResponse, Response
from fastapi.staticfiles import StaticFiles
from bs4 import BeautifulSoup
import aioredis

# Cél domainek
TARGET_DOMAINS = [
    "https://www.jysk.hu",
    "https://www.dm.hu",
    "https://www.douglas.hu",
    "https://www.euronics.hu",
    "https://www.praktiker.hu",
    "https://www.moebelix.hu",
]

# Redis
REDIS_URL = "redis://localhost:6379/0"

# Feltérképezési limitek
MAX_PAGES_PER_DOMAIN = 600   # óvatos, de teljes site-crawlhoz értelmes kompromisszum
CONCURRENCY_PER_DOMAIN = 6
REQUEST_TIMEOUT = 20
RECRAWL_SECONDS = 15 * 60    # domain frissítése max 15 percenként

# User-Agent
USER_AGENT = "DealsPWA/1.0 (+contact: admin@example.com) respectful-crawler"

# A kedvezmény-számítás mintái
PRICE_RE = re.compile(r"(\d[\d\.\s]{0,3}\d(?:[.,]\d{2})?)\s*(?:Ft|HUF)", re.IGNORECASE)
PCT_RE = re.compile(r"(\d{1,3})\s*%", re.IGNORECASE)
SALE_WORDS = re.compile(r"(akci[oó]|le[aá]raz[aá]s|ki[aá]rus[ií]t[aá]s|kedvezm[eé]ny|outlet|sale)", re.IGNORECASE)

# Robots.txt cache és sitemap-ok
class Robots:
    def __init__(self, allow_all: bool, disallows: List[str], crawl_delay: Optional[float], sitemaps: List[str]):
        self.allow_all = allow_all
        self.disallows = disallows
        self.crawl_delay = crawl_delay
        self.sitemaps = sitemaps

def parse_robots(text: str) -> Robots:
    user_agent = None
    disallows = []
    crawl_delay = None
    sitemaps = []
    allow_all = True
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if line.lower().startswith("user-agent:"):
            ua = line.split(":", 1)[1].strip()
            user_agent = ua
        elif line.lower().startswith("disallow:") and (user_agent in ("*", USER_AGENT) or user_agent == "*"):
            path = line.split(":", 1)[1].strip()
            if path:
                disallows.append(path)
                allow_all = False
        elif line.lower().startswith("crawl-delay:"):
            try:
                crawl_delay = float(line.split(":", 1)[1].strip())
            except:
                pass
        elif line.lower().startswith("sitemap:"):
            sm = line.split(":", 1)[1].strip()
            sitemaps.append(sm)
    return Robots(allow_all=allow_all, disallows=disallows, crawl_delay=crawl_delay, sitemaps=sitemaps)

def is_allowed(robots: Robots, url_path: str) -> bool:
    # egyszerű Disallow prefix-egyezés
    for rule in robots.disallows:
        if url_path.startswith(rule):
            return False
    return True

# FastAPI
app = FastAPI(title="Akciófigyelő PWA", version="1.0")

# statikus: index.html, manifest, service-worker
app.mount("/static", StaticFiles(directory="static"), name="static")

# WebSocket menedzser
class WSManager:
    def __init__(self):
        self.active: Set[WebSocket] = set()

    async def connect(self, ws: WebSocket):
        await ws.accept()
        self.active.add(ws)

    def disconnect(self, ws: WebSocket):
        self.active.discard(ws)

    async def broadcast(self, message: dict):
        dead = []
        for ws in list(self.active):
            try:
                await ws.send_text(json.dumps(message, ensure_ascii=False))
            except:
                dead.append(ws)
        for ws in dead:
            self.disconnect(ws)

ws_manager = WSManager()

# Redis init
redis: aioredis.Redis = None

@app.on_event("startup")
async def startup():
    global redis
    redis = await aioredis.from_url(REDIS_URL, decode_responses=True)
    # induló crawl trigger
    asyncio.create_task(periodic_crawl())

@app.on_event("shutdown")
async def shutdown():
    if redis:
        await redis.close()

# HTTP kliens
def http_client():
    return httpx.AsyncClient(timeout=REQUEST_TIMEOUT, headers={"User-Agent": USER_AGENT}, follow_redirects=True)

async def fetch_text(client: httpx.AsyncClient, url: str) -> Optional[str]:
    try:
        r = await client.get(url)
        if r.status_code == 200 and r.headers.get("content-type","").lower().startswith(("text/html","text/plain","application/xml","text/xml")):
            return r.text
    except Exception:
        return None
    return None

async def get_robots(client: httpx.AsyncClient, base: str) -> Robots:
    parsed = urlparse(base)
    robots_url = f"{parsed.scheme}://{parsed.netloc}/robots.txt"
    cache_key = f"robots:{parsed.netloc}"
    cached = await redis.get(cache_key)
    if cached:
        try:
            obj = json.loads(cached)
            return Robots(obj["allow_all"], obj["disallows"], obj["crawl_delay"], obj["sitemaps"])
        except:
            pass
    text = await fetch_text(client, robots_url)
    robots = parse_robots(text or "")
    await redis.set(cache_key, json.dumps({
        "allow_all": robots.allow_all,
        "disallows": robots.disallows,
        "crawl_delay": robots.crawl_delay,
        "sitemaps": robots.sitemaps
    }), ex=24*3600)
    return robots

def normalize_url(base: str, href: str) -> Optional[str]:
    if not href:
        return None
    href = urljoin(base, href)
    href, _ = urldefrag(href)
    p = urlparse(href)
    if p.scheme not in ("http","https"):
        return None
    return href

def is_same_domain(root: str, url: str) -> bool:
    return urlparse(root).netloc == urlparse(url).netloc

def extract_links(base_url: str, html: str) -> List[str]:
    soup = BeautifulSoup(html, "html.parser")
    links = []
    for a in soup.find_all("a", href=True):
        u = normalize_url(base_url, a.get("href"))
        if u:
            links.append(u)
    return links

def extract_candidates(base_url: str, html: str) -> List[Dict]:
    # Vesz ki akciós blokkokat, százalékot vagy árpárost keres
    results = []
    soup = BeautifulSoup(html, "html.parser")

    text = soup.get_text(" ", strip=True)
    has_sale_word = bool(SALE_WORDS.search(text))

    # Termékkártya-szerű blokkok
    cards = soup.select("[class*='product'],[class*='card'],[class*='item'],[class*='tile']")
    if not cards:
        cards = soup.find_all(["article","li","div","section"])
    for node in cards[:200]:  # lapos korlát
        t = node.get_text(" ", strip=True)
        if not t:
            continue
        pct = None
        pct_match = PCT_RE.search(t)
        if pct_match:
            try:
                pct_val = int(pct_match.group(1))
                if 0 < pct_val <= 100:
                    pct = pct_val
            except:
                pass
        prices = PRICE_RE.findall(t)
        old_price = None
        new_price = None
        if len(prices) >= 2:
            # heur: nagyobb mint régi, kisebb mint új ár
            nums = []
            for raw in prices[:3]:
                n = float(raw.replace(" ", "").replace(".", "").replace(",", "."))
                nums.append(n)
            nums = sorted(nums)
            if len(nums) >= 2:
                old_price, new_price = nums[-1], nums if nums < nums[-1] else None

        if pct is None and old_price and new_price and old_price > 0 and new_price and new_price < old_price:
            pct = int(round((old_price - new_price) / old_price * 100.0))

        if pct or has_sale_word or (old_price and new_price):
            # cím/URL kigyűjtése
            title = None
            for sel in ["[class*='title']","h1","h2","h3",".name",".product-name"]:
                el = node.select_one(sel)
                if el:
                    title = el.get_text(" ", strip=True)
                    break
            if not title:
                title = (t[:120] + "…") if len(t) > 120 else t

            link = None
            a = node.find("a", href=True)
            if a:
                link = normalize_url(base_url, a["href"])

            results.append({
                "title": title,
                "pct": pct,
                "old_price": old_price,
                "new_price": new_price,
                "url": link or base_url
            })
    # Ha semmi nem volt, de az oldalon vannak akciós kulcsszavak, tegyünk fel egy oldalszintű jelzést
    if not results and has_sale_word:
        results.append({
            "title": "Akció/Kiárusítás jelzése az oldalon",
            "pct": None,
            "old_price": None,
            "new_price": None,
            "url": base_url
        })
    return results

async def process_page(domain_root: str, url: str, client: httpx.AsyncClient, robots: Robots) -> Dict:
    parsed = urlparse(url)
    if not is_allowed(robots, parsed.path):
        return {"url": url, "links": [], "deals": []}
    html = await fetch_text(client, url)
    if not html:
        return {"url": url, "links": [], "deals": []}
    links = [u for u in extract_links(url, html) if is_same_domain(domain_root, u)]
    deals = extract_candidates(url, html)
    return {"url": url, "links": links, "deals": deals}

async def crawl_domain(domain_root: str):
    domain = urlparse(domain_root).netloc
    state_key = f"crawl:state:{domain}"
    last_ts = await redis.get(state_key)
    now = time.time()
    if last_ts and (now - float(last_ts) < RECRAWL_SECONDS):
        return  # túl friss, kihagy
    await redis.set(state_key, str(now), ex=RECRAWL_SECONDS)

    visited_key = f"crawl:visited:{domain}"
    queue_key = f"crawl:queue:{domain}"
    deals_key = f"deals:{domain}"

    await redis.delete(visited_key)
    await redis.delete(queue_key)
    await redis.delete(deals_key)

    async with http_client() as client:
        robots = await get_robots(client, domain_root)
        start_html = await fetch_text(client, domain_root)
        if not start_html:
            return
        # Indító linkek: kezdőlap + sitemap URL-ek
        start_urls = {domain_root}
        for sm in robots.sitemaps[:5]:
            start_urls.add(sm)
        for u in start_urls:
            await redis.lpush(queue_key, u)

        sem = asyncio.Semaphore(CONCURRENCY_PER_DOMAIN)
        visited: Set[str] = set()

        async def worker():
            while True:
                url = await redis.rpop(queue_key)
                if not url:
                    break
                if url in visited or len(visited) >= MAX_PAGES_PER_DOMAIN:
                    continue
                visited.add(url)
                await redis.sadd(visited_key, url)
                async with sem:
                    try:
                        res = await process_page(domain_root, url, client, robots)
                    except Exception:
                        continue
                # új linkek
                for link in res["links"][:50]:
                    if link not in visited:
                        await redis.lpush(queue_key, link)
                # talált ajánlatok mentése
                for d in res["deals"]:
                    d["domain"] = domain
                    await redis.rpush(deals_key, json.dumps(d, ensure_ascii=False))
                    # azonnali push a kliensnek
                    await ws_manager.broadcast({"type": "deal", "payload": d})

        workers = [asyncio.create_task(worker()) for _ in range(CONCURRENCY_PER_DOMAIN)]
        await asyncio.gather(*workers)

    # Tartós index frissítés domainre
    # nincs külön teendő, a listában vannak az elemek

async def periodic_crawl():
    # első körben mind
    while True:
        try:
            for root in TARGET_DOMAINS:
                await crawl_domain(root)
        except Exception:
            pass
        await asyncio.sleep(120)  # 2 percenként ciklus

def normalize_and_rank(all_deals: List[Dict], sort_by: str) -> List[Dict]:
    # kedvezmény kiszámítás, sorrendezés
    out = []
    for d in all_deals:
        pct = d.get("pct")
        oldp = d.get("old_price")
        newp = d.get("new_price")
        if pct is None and oldp and newp and oldp > 0 and newp < oldp:
            pct = int(round((oldp - newp) / oldp * 100.0))
        d["pct"] = pct
        out.append(d)
    if sort_by == "pct_desc":
        out.sort(key=lambda x: (x.get("pct") or -1), reverse=True)
    elif sort_by == "new_price_asc":
        out.sort(key=lambda x: (x.get("new_price") or 1e18))
    else:
        out.sort(key=lambda x: x.get("title",""))
    return out

@app.get("/", response_class=HTMLResponse)
async def index():
    return FileResponse("index.html")

@app.get("/manifest.webmanifest")
async def manifest():
    data = {
        "name": "Akciófigyelő",
        "short_name": "Akciók",
        "lang": "hu",
        "display": "standalone",
        "background_color": "#0b0f1a",
        "theme_color": "#0b0f1a",
        "start_url": "/",
        "icons": [
            {"src": "/static/icon-192.png", "sizes": "192x192", "type": "image/png"},
            {"src": "/static/icon-512.png", "sizes": "512x512", "type": "image/png"}
        ]
    }
    return JSONResponse(data)

@app.get("/service-worker.js")
async def sw():
    return FileResponse("static/service-worker.js", media_type="application/javascript")

@app.websocket("/ws")
async def websocket_endpoint(ws: WebSocket):
    await ws_manager.connect(ws)
    try:
        while True:
            await ws.receive_text()
    except WebSocketDisconnect:
        ws_manager.disconnect(ws)

@app.get("/api/deals")
async def api_deals(q: Optional[str] = Query(None), sort: str = Query("pct_desc")):
    # összegyűjt minden domainekről
    all_deals = []
    for root in TARGET_DOMAINS:
        domain = urlparse(root).netloc
        deals_key = f"deals:{domain}"
        items = await redis.lrange(deals_key, 0, -1)
        for it in items:
            try:
                d = json.loads(it)
                all_deals.append(d)
            except:
                pass
    # szűrés
    if q:
        qq = q.lower()
        all_deals = [d for d in all_deals if qq in (d.get("title","").lower())]
    ranked = normalize_and_rank(all_deals, sort)
    return JSONResponse({"items": ranked[:1000]})

# Egyszeri kézi újraindítás endpoint (opcionális)
@app.post("/api/reindex")
async def reindex():
    for root in TARGET_DOMAINS:
        await crawl_domain(root)
    return JSONResponse({"status":"ok"})

