        const pct = it.pct != null ? `<span class="badge">-${it.pct}%</span>` : '';
        const prices = (it.new_price?fmtPrice(it.new_price):'') + (it.old_price? ` · <s>${fmtPrice(it.old_price)}</s>`:'');
        const dom = document.createElement('div');
        dom.className='card';
        dom.innerHTML = `
          <div class="title">${it.title}</div>
          <div class="meta">
            ${pct}
            <span>${it.domain||''}</span>
            <a class="link" rel="nofollow noopener" target="_blank" href="${it.url}">Megnyitás</a>
          </div>
          <div class="meta">${prices}</div>
        `;
        listEl.appendChild(dom);
      }
    }

    async function load(){
      const url = new URL(location.origin + '/api/deals');
      if (query) url.searchParams.set('q', query);
      if (sort) url.searchParams.set('sort', sort);
      const r = await fetch(url.toString());
      const data = await r.json();
      items = data.items || [];
      render();
    }

    // WebSocket élő frissítés
    function wsConnect(){
      try{
        const wsProto = location.protocol === 'https:' ? 'wss' : 'ws';
        const ws = new WebSocket(wsProto + '://' + location.host + '/ws');
        ws.onmessage = (e)=>{
          const msg = JSON.parse(e.data);
          if (msg.type === 'deal'){
            // beszúrjuk és újrarendezzük
            items.unshift(msg.payload);
            // reapply sort
            if (sort==='pct_desc'){
              items.sort((a,b)=> (b.pct??-1) - (a.pct??-1));
            }else if (sort==='new_price_asc'){
              items.sort((a,b)=> (a.new_price??1e18) - (b.new_price??1e18));
            }else{
              items.sort((a,b)=> (a.title||'').localeCompare(b.title||''));
            }
            render();
          }
        };
        ws.onclose = ()=> setTimeout(wsConnect, 3000);
      }catch(e){
        setTimeout(wsConnect, 3000);
      }
    }

    wsConnect();
    load();
  </script>
</body>
</html>

A fenti frontend iPhoneon natív érzetet ad (PWA, fullscreen, glassmorphism), és valós időben frissül WebSocketen át; a lista rendezhető úgy, hogy a legnagyobb kedvezmény legyen elöl. [1][3]

